def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # recent cooperation ratios
    recent_len = min(12, n)
    recent = opp[n-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    total_c = sum(1 for a in opp if a == 'C')
    total_ratio = total_c / n

    # consecutive opponent defections
    run_d = 0
    for a in reversed(opp):
        if a == 'D':
            run_d += 1
        else:
            break

    # consecutive opponent cooperations
    run_c = 0
    for a in reversed(opp):
        if a == 'C':
            run_c += 1
        else:
            break

    # Strongly cooperative opponent: lock in cooperation, rare probe
    if n >= 8 and total_ratio >= 0.95 and run_d == 0:
        if n < 95 and n % 23 == 0 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: cooperate, punish only sustained defection
    if recent_ratio >= 0.75:
        if run_d >= 3:
            return 'D'
        if opp[-1] == 'D':
            # brief single retaliation, then resume
            if run_d == 2:
                return 'D'
            # single defection: retaliate once but often forgive
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        return 'C'

    # Very hostile opponent: defect mostly, occasional probe to reopen
    if total_ratio <= 0.15:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Hostile-ish: defend but try periodic resets
    if recent_ratio <= 0.35:
        if run_c >= 2:
            return 'C'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Mixed regime: forgiving tit-for-tat with coordinated repair
    if opp[-1] == 'C':
        # reward cooperation, occasionally close last few rounds with defect if clearly ahead
        if n >= 97 and recent_ratio > 0.5:
            return 'D'
        return 'C'

    # opponent just defected
    if me[-1] == 'D':
        # mutual defection: attempt repair
        if run_d >= 3:
            return 'D'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # we cooperated, they defected (exploitation)
    if run_d >= 3:
        return 'D'
    if recent_ratio >= 0.5:
        # forgive single defections frequently to avoid lock-in
        if run_d == 1 and rng.random() < 0.7:
            return 'C'
        return 'D'
    if rng.random() < 0.2:
        return 'C'
    return 'D'
